/* bn_fx_pair.h — the FX loop's resampler pair: the send goes DOWN to the host rate, the return comes back UP.
 *
 * Its own short FIRs rather than a copy of the main oversampler (bn_oversample's 95-tap linear-phase halfbands,
 * whose round trip is 47 base-rate samples at 2x and 71 at 4x), since the loop's round trip is part of the declared
 * latency. The arms are generated by tools/gen_fx_pair.py into bn_fx_pair_coeffs.h; `-DBN_FX_PAIR=<arm>` picks one
 * at build time.
 *
 * Per 2x stage, a FIR h in polyphase form (even taps h[2j], odd taps h[2j+1], each branch trimmed to its non-zero
 * span, so a halfband's odd branch is its centre alone):
 *   up   (rate r -> 2r): out[2i] = 2 sum_j h[2j] x[i-j],   out[2i+1] = 2 sum_j h[2j+1] x[i-j]
 *   down (rate 2r -> r): y[i]   = sum_j h[2j] v[2(i-j)] + sum_j h[2j+1] v[2(i-j)-1]
 * Stage 0 is base <-> 2x; every later stage uses the arm's stage-1 filter.
 *
 * The round trip (down then up) is sum_s delay_s / 2^s base samples; when it is fractional (a linear-phase halfband
 * chain at 4x) a pure delay of `pad` high-rate samples after the way up makes it whole, as bn_oversample does.
 * No allocation on the audio path: every buffer is sized at bn_fxp_init for the largest block declared. */
#ifndef BN_FX_PAIR_H
#define BN_FX_PAIR_H

#include <stddef.h>

#ifndef BN_FX_PAIR
#define BN_FX_PAIR 3               /* the arm (bn_fx_pair_coeffs.h: 0 hb95 · 1 hb59 · 2 ld20 · 3 ld16 · 4 ld12); the product builds 4 = ld12 (plugin.mk) */
#endif

#define BN_FXP_MAX_STAGES 3         /* up to 8x */
#define BN_FXP_RING       128       /* history per branch: holds a branch span of up to 128 taps */

typedef struct {
    int     arm, factor, n_stages;
    size_t  max_block;
    double* up_h[BN_FXP_MAX_STAGES];      /* up: input history, written twice (2 * RING) */
    double* dn_e[BN_FXP_MAX_STAGES];      /* down: even-sample history, written twice */
    double* dn_o[BN_FXP_MAX_STAGES];      /* down: odd-sample history, written twice */
    int     up_pos[BN_FXP_MAX_STAGES], dn_pos[BN_FXP_MAX_STAGES];
    double* scratch_a;
    double* scratch_b;
    int     pad, pad_pos;
    double  pad_ring[8];
} BnFxPair;

int  bn_fxp_init(BnFxPair* p, int factor, size_t max_block);            /* the build's arm, BN_FX_PAIR */
int  bn_fxp_init_arm(BnFxPair* p, int arm, int factor, size_t max_block);
void bn_fxp_free(BnFxPair* p);
void bn_fxp_reset(BnFxPair* p);

/* `n` samples up to n*factor in `out` (room for n*factor). */
void bn_fxp_up(BnFxPair* p, const double* in, size_t n, double* out);
/* n*factor samples down to `n` in `out`. */
void bn_fxp_down(BnFxPair* p, const double* in, size_t n, double* out);

/* the round trip, down then up, in base-rate samples: exact (the pad included, so whole) and as an integer */
double bn_fxp_latency_exact(const BnFxPair* p);
int    bn_fxp_latency(const BnFxPair* p);
/* the same without an instance, for a gate (the build's arm) */
int    bn_fxp_roundtrip(int factor);
const char* bn_fxp_arm_name(void);

#endif /* BN_FX_PAIR_H */
